buggy.described_examples:
import jax
import jax.numpy as jnp
from jax import lax

_NAME = (
    "jax.grad(lambda x: lax.tanh(x, accuracy=lax.AccuracyMode.HIGHEST))"
    " at large float32 |x| (e.g. x=20 or x=80)"
)

try:
    grad_tanh = jax.grad(
        lambda x: lax.tanh(x, accuracy=lax.AccuracyMode.HIGHEST)
    )
    result = {}
    for x in (20.0, 80.0):
        result["x=%g" % x] = float(grad_tanh(jnp.float32(x)))
    probe(_NAME, result)
except Exception as e:
    probe_exception(_NAME, e)

